1	/**
2	 * 会话级切店（右上角头像 → 切换 →「切换店铺」弹窗）
3	 * 对齐 temu-plugin content.js，多 mall 共用账号时必须用此方式，不能用「来源店铺」筛选。
4	 */
5	import { log } from './logger.js';
6	
7	const SWITCH_HELPERS = `
8	  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
9	  const visible = (el) => {
10	    if (!el) return false;
11	    const r = el.getBoundingClientRect();
12	    return r.width > 0 && r.height > 0;
13	  };
14	  const textEls = (re, maxLen = 40) =>
15	    [...document.querySelectorAll('*')].filter((e) => {
16	      const t = (e.textContent || '').trim();
17	      return re.test(t) && t.length <= maxLen;
18	    });
19	  const clickableAncestor = (el) => {
20	    let p = el;
21	    for (let i = 0; i < 6 && p; i++, p = p.parentElement) {
22	      if (p.tagName === 'BUTTON' || p.getAttribute('role') === 'button') return p;
23	    }
24	    return el;
25	  };
26	  const realClick = (el) => {
27	    if (!el) return;
28	    const opts = { bubbles: true, cancelable: true, view: window };
29	    for (const type of ['pointerdown', 'mousedown', 'mouseup', 'click']) {
30	      el.dispatchEvent(new MouseEvent(type, opts));
31	    }
32	  };
33	  const waitFor = async (fn, timeout = 8000, step = 300) => {
34	    const t0 = Date.now();
35	    while (Date.now() - t0 < timeout) {
36	      const v = fn();
37	      if (v) return v;
38	      await sleep(step);
39	    }
40	    return null;
41	  };
42	  function findStoreNameEl() {
43	    const W = window.innerWidth;
44	    let best = null;
45	    for (const el of document.querySelectorAll('span,a,div,button,p')) {
46	      const t = (el.textContent || '').trim();
47	      if (!/^[A-Za-z][A-Za-z0-9]*(?:\\s[A-Za-z0-9]+){0,3}$/.test(t)) continue;
48	      if (t.length < 2 || t.length > 30) continue;
49	      if (/^(Seller Central|Beta|NEW|SKC|SKU|USD|Best Seller)$/i.test(t)) continue;
50	      if (/^[A-Z0-9]+$/.test(t)) continue;
51	      if (el.children.length > 2) continue;
52	      const r = el.getBoundingClientRect();
53	      if (r.width === 0 || r.top < 0 || r.top > 90) continue;
54	      if (r.left < W * 0.5) continue;
55	      if (!best || r.left > best.left) best = { el, left: r.left };
56	    }
57	    return best ? best.el : null;
58	  }
59	  function readStoreName() {
60	    const el = findStoreNameEl();
61	    return el ? (el.textContent || '').trim() : null;
62	  }
63	  async function openStoreModal() {
64	    // 点顶栏最右侧区域的「切换」
65	    const switches = textEls(/^切换$/, 6).filter(visible);
66	    let btn = switches[switches.length - 1];
67	    if (!btn) {
68	      // 点头像附近
69	      const av = [...document.querySelectorAll('img,div,span')].find((e) => {
70	        const r = e.getBoundingClientRect();
71	        return r.top >= 0 && r.top < 80 && r.left > window.innerWidth * 0.85 && r.width > 20 && r.height > 20;
72	      });
73	      if (av) realClick(av);
74	      await sleep(400);
75	      const again = textEls(/^切换$/, 6).filter(visible);
76	      btn = again[again.length - 1];
77	    }
78	    if (btn) realClick(clickableAncestor(btn));
79	    await sleep(600);
80	    const modal = await waitFor(() => {
81	      const t = document.body.innerText || '';
82	      return /切换店铺|您的账户存在/.test(t) ? true : null;
83	    }, 5000, 200);
84	    return !!modal;
85	  }
86	`;
87	
88	export async function readCurrentStoreName(page) {
89	  return page.evaluate((helpers) => {
90	    // eslint-disable-next-line no-eval
91	    eval(helpers);
92	    return readStoreName();
93	  }, SWITCH_HELPERS);
94	}
95	
96	/**
97	 * 切换到目标店铺（会话级）。已是当前店则 ok。
98	 * @returns {Promise<{ok:boolean,msg:string}>}
99	 */
100	export async function switchSessionStore(page, target) {
101	  const cur = await readCurrentStoreName(page);
102	  if (cur && cur === target) {
103	    log.info(`已是当前店：${target}`);
104	    return { ok: true, msg: 'already' };
105	  }
106	  log.info(`会话切店 → ${target}（当前=${cur || '未知'}）`);
107	  const result = await page.evaluate(async (helpers, targetName) => {
108	    // eslint-disable-next-line no-eval
109	    eval(helpers);
110	    if (!(await openStoreModal())) return { ok: false, msg: '打不开切换店铺弹窗' };
111	    await sleep(400);
112	    const esc = String(targetName).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
113	    const re = new RegExp(esc);
114	    // 弹窗内含店名的行
115	    const candidates = [...document.querySelectorAll('div,li,tr,span')].filter((e) => {
116	      if (!visible(e)) return false;
117	      const t = (e.textContent || '').trim();
118	      return re.test(t) && /切换|半托管|全托管/.test(t) && t.length < 200;
119	    });
120	    // 取最短匹配容器
121	    candidates.sort((a, b) => (a.textContent || '').length - (b.textContent || '').length);
122	    const row = candidates[0];
123	    if (!row) return { ok: false, msg: '弹窗里没找到店铺 ' + targetName };
124	    let btn = [...row.querySelectorAll('button,[role=button]')].find(
125	      (b) => /^\s*切换\s*$/.test((b.textContent || '').trim()) && !b.disabled && b.getAttribute('aria-disabled') !== 'true',
126	    );
127	    if (!btn) {
128	      const allSwitch = textEls(/^切换$/, 6)
129	        .map(clickableAncestor)
130	        .filter((b) => b && !b.disabled && visible(b));
131	      btn = allSwitch.find((b) => row.contains(b)) || allSwitch[allSwitch.length - 1];
132	    }
133	    if (!btn) return { ok: false, msg: '没找到可点的切换按钮（可能已是当前店）' };
134	    realClick(btn);
135	    return { ok: true, msg: 'clicked' };
136	  }, SWITCH_HELPERS, target);
137	
138	  if (!result.ok) {
139	    log.warn(`切店失败：${result.msg}`);
140	    await page.keyboard.press('Escape').catch(() => {});
141	    return result;
142	  }
143	  // 等顶栏店名变化或导航完成
144	  await page.waitForTimeout(2500);
145	  const deadline = Date.now() + 25000;
146	  while (Date.now() < deadline) {
147	    const name = await readCurrentStoreName(page);
148	    if (name === target) {
149	      log.info(`切店成功：${target}`);
150	      return { ok: true, msg: 'switched' };
151	    }
152	    await page.waitForTimeout(800);
153	  }
154	  const after = await readCurrentStoreName(page);
155	  if (after === target) return { ok: true, msg: 'switched-late' };
156	  log.warn(`切店超时，当前显示=${after || '未知'}，目标=${target}`);
157	  return { ok: false, msg: `timeout current=${after}` };
